css:
/* Global Styles */

body {

    font-family: Arial, sans-serif;

    margin: 0;

    padding: 0;

    box-sizing: border-box;

    min-height: 100vh; /* Ensure full viewport height */

}

.container {

    max-width: 100%; /* Further increased max width */

    margin: 0 auto; /* Center the container */

    padding: 30px;

}.logo-container {
    display: flex;
    align-items: center;
    gap: 15px; /* Space between logo and text */
    padding: 10px 20px; /* Adjust spacing */
}

/* Logo styling */
.logo {
    max-width: 80px; /* Adjust as per your logo size */
    height: auto;
}



/* Highlight second part of the company name */
.highlight {
    color: #FFA500; /* Orange color like in your screenshot */
}


/* Header Styling */

.header {

    display: flex;

    justify-content: space-between;

    margin-bottom: 30px;

}

.header .details-left {

    text-align: left; /* Align left for Lead Name and Address */

}

.header .details-right {

    text-align: right; /* Align right for Date and Quotation ID */

}

.header .details {

    font-size: 16px; /* Increased font size */

    line-height: 1.8;

}



.title {

    text-align: center;

    margin-bottom: 30px;

    margin-top: -30px; /* Reduced top margin for Solar EPC heading */

}


.table {

    max-width: 100%; /* Centered and limited width */

    margin: 0 auto; /* Center the table */

    border-collapse: collapse;

    margin-top: 30px;

    font-size: 16px; /* Consistent font size for table data */

}
/* Ensure every column (th and td) has a black border */
/*.table-bordered th, .table-bordered td {*/
/*    border: 1px solid black !important;*/
/*}*/


.table-bordered th, .table-bordered td {
        border: 1px solid #000;


    padding: 8px; /* Reduced padding for smaller cells */

    text-align: left;

}

.table-bordered th {

    background-color: #2b2a28;

    text-align: center; /* Center align header */
     color: white;

}
/* Apply alternating row colors */
.table-bordered tbody tr:nth-child(even) {
    background-color: #f2f2f2;
}

/* Responsive Design */

@media (max-width: 768px) {

    .header {

        flex-direction: column;

        text-align: center;

    }

    .table {

        width: 100%; /* Full width on small screens */

    }

}
